package in.aicon.pocket;
import android.content.Context;import java.util.*;import java.util.concurrent.*;

/** Explicit ledger selection and foreground work ownership used by QuickActivity.
 * Identity verification alone never switches, copies or syncs. Tokens live only here;
 * only a matching session can use one. Stale callbacks are discarded before notifying
 * UI, which rebuilds its views on a selection change.
 */
public final class LedgerController implements AutoCloseable {
 public enum State { LOCAL, OFFLINE, READY, SYNCING, CONFLICT, NEEDS_SIGN_IN, RESET_PENDING, RESET_DETECTED, DISCONNECT_PENDING, RETRY, ERROR }
 public static final class Status {public final State state;public final String subject,email;public final long lastSyncMillis;Status(State state,String subject,String email,long lastSyncMillis){this.state=state;this.subject=subject;this.email=email;this.lastSyncMillis=lastSyncMillis;}}
 public interface Listener {void changed(Status status,boolean ledgerChanged);}
 interface Revoke {void revoke(Context context,AccountDirectory.Entry entry)throws Exception;}
 interface Runner {SyncEngine.Result sync(LedgerSession session,LedgerSession.Ticket ticket,VerifiedDriveAccess access)throws Exception;}
 private final Context context;private final AccountDirectory accounts;private final Executor dispatcher;private final ExecutorService worker;private final Listener listener;private final Runner runner;
 private LedgerSession session;private String subject,email;private VerifiedDriveAccess activeAccess,pendingAccess;private long generation=1,lastSync,seenRevision;private boolean closed,busy;private State state;private ResetBarrier.Check observedReset;
 public LedgerController(Context context,Executor dispatcher,Listener listener)throws Exception{this(context,dispatcher,listener,Executors.newSingleThreadExecutor(),(s,t,a)->s.synchronize(t,a,()->{try{AccountDirectory directory=new AccountDirectory(context);if(directory.disconnectPending(a.subject)||!a.subject.equals(directory.selectedSubject()))throw new IllegalStateException("Google ledger is no longer selected for sync");}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("Account selection cannot be verified",e);}}));}
 LedgerController(Context context,Executor dispatcher,Listener listener,ExecutorService worker,Runner runner)throws Exception{this.context=context.getApplicationContext();accounts=new AccountDirectory(this.context);this.dispatcher=Objects.requireNonNull(dispatcher);this.listener=Objects.requireNonNull(listener);this.worker=worker;this.runner=runner;subject=accounts.selectedSubject();session=subject==null?LedgerSession.local(this.context):LedgerSession.remembered(this.context,accounts,subject);email=subject==null?null:accounts.find(subject).email;state=initialState();seenRevision=subject==null?0:session.snapshot(session.ticket()).revision;if(subject!=null)lastSync=new SyncStatusStore(context,subject).get().success;}
 private State initialState()throws Exception{if(subject==null)return State.LOCAL;if(accounts.disconnectPending(subject))return State.DISCONNECT_PENDING;if(session.resetPending())return State.RESET_PENDING;if(session.conflict(session.ticket())!=null||session.repaymentReview(session.ticket())!=null)return State.CONFLICT;return activeAccess==null?State.OFFLINE:State.READY;}
 private void open(){if(closed)throw new IllegalStateException("Ledger controller closed");}
 public synchronized Status status(){open();return new Status(state,subject,email,lastSync);}
 public synchronized LedgerSession session(){open();return session;}
 public synchronized List<AccountDirectory.Entry> accounts()throws Exception{open();return accounts.entries();}
 private void notifyChange(boolean changed){Status result=status();long g=generation;dispatcher.execute(()->{synchronized(LedgerController.this){if(closed||generation!=g)return;}listener.changed(result,changed);});}
 public synchronized void localEdited()throws Exception{open();if(subject!=null)seenRevision=session.snapshot(session.ticket()).revision;}
 public synchronized void refreshExternal()throws Exception{open();if(busy)return;String durable=accounts.selectedSubject();if(!Objects.equals(durable,subject)){select(durable);return;}if(subject==null)return;long revision=session.snapshot(session.ticket()).revision;boolean changed=revision!=seenRevision;seenRevision=revision;SyncStatusStore.Status saved=new SyncStatusStore(context,subject).get();lastSync=Math.max(lastSync,saved.success);State initial=initialState();if(initial==State.DISCONNECT_PENDING||initial==State.CONFLICT||initial==State.RESET_PENDING)state=initial;else if(observedReset!=null)state=State.RESET_DETECTED;else if(saved.state.equals("RESET_DETECTED"))state=State.RESET_DETECTED;else if(saved.state.equals("NEEDS_SIGN_IN"))state=State.NEEDS_SIGN_IN;else if(saved.state.equals("ERROR"))state=State.ERROR;else if(saved.state.equals("RETRY"))state=State.RETRY;else if(saved.state.equals("SYNCING"))state=State.SYNCING;else state=initial;notifyChange(changed);}
 public synchronized boolean resetObserved(){open();return observedReset!=null;}
 /** First connection: remember identity, then show a separate Use this ledger choice. */
 public synchronized void verified(VerifiedDriveAccess access)throws Exception{open();access.accessToken(access.subject);accounts.record(access);if(pendingAccess!=null&&pendingAccess!=activeAccess&&pendingAccess!=access)pendingAccess.clear();pendingAccess=access;}
 /** Reconnect only the ledger that requested authorization, never picker fallback. */
 public synchronized void reconnected(String expectedSubject,VerifiedDriveAccess access)throws Exception{open();if(accounts.disconnectPending(access.subject)){access.clear();throw new IllegalStateException("Finish disconnecting this Google account first");}if(subject==null||!subject.equals(expectedSubject)||!subject.equals(access.subject)){access.clear();throw new IllegalStateException("Selected ledger changed. No connection applied.");}access.accessToken(subject);accounts.record(access);if(activeAccess!=null&&activeAccess!=access)activeAccess.clear();activeAccess=access;email=access.email;state=initialState();notifyChange(false);}
 public synchronized void selectLocal()throws Exception{select(null);}
 public synchronized void selectKnown(String chosenSubject)throws Exception{Objects.requireNonNull(chosenSubject);select(chosenSubject);}
 private void select(String selected)throws Exception{open();if(busy)throw new IllegalStateException("Wait for the current sync before switching ledgers.");if(Objects.equals(subject,selected)){if(pendingAccess!=null&&Objects.equals(pendingAccess.subject,subject)){VerifiedDriveAccess access=pendingAccess;pendingAccess=null;reconnected(subject,access);}return;}VerifiedDriveAccess nextAccess=pendingAccess!=null&&Objects.equals(pendingAccess.subject,selected)?pendingAccess:null;if(nextAccess!=null)try{nextAccess.accessToken(selected);}catch(DriveAppData.NeedsSignIn e){nextAccess.clear();nextAccess=null;}
  LedgerSession next=selected==null?LedgerSession.local(context):LedgerSession.remembered(context,accounts,selected);String nextEmail;try{nextEmail=selected==null?null:accounts.find(selected).email;if(selected==null)accounts.selectLocal();else accounts.selectKnown(selected);}catch(Exception e){next.close();throw e;}
  LedgerSession old=session;VerifiedDriveAccess oldAccess=activeAccess;session=next;subject=selected;email=nextEmail;activeAccess=nextAccess;if(pendingAccess!=null&&pendingAccess!=nextAccess&&pendingAccess!=oldAccess)pendingAccess.clear();pendingAccess=null;generation=Math.addExact(generation,1);lastSync=0;seenRevision=selected==null?0:session.snapshot(session.ticket()).revision;observedReset=null;old.close();if(oldAccess!=null&&oldAccess!=nextAccess)oldAccess.clear();state=initialState();SyncWorkScheduler.selection(context,subject);notifyChange(true);
 }
 public synchronized void forget(String selected)throws Exception{open();if(Objects.equals(subject,selected))selectLocal();accounts.forget(selected);if(pendingAccess!=null&&pendingAccess.subject.equals(selected)){pendingAccess.clear();pendingAccess=null;}notifyChange(false);}
 public synchronized boolean sync(){open();if(busy||subject==null)return false;if(accounts.disconnectPending(subject)){state=State.DISCONNECT_PENDING;notifyChange(false);return false;}if(session.resetPending()){state=State.RESET_PENDING;notifyChange(false);return false;}if(observedReset!=null){state=State.RESET_DETECTED;notifyChange(false);return false;}if(activeAccess==null){state=State.NEEDS_SIGN_IN;notifyChange(false);return false;}try{activeAccess.accessToken(subject);}catch(Exception e){activeAccess.clear();activeAccess=null;state=State.NEEDS_SIGN_IN;notifyChange(false);return false;}
  busy=true;state=State.SYNCING;final long g=generation;final LedgerSession owner=session;final LedgerSession.Ticket ticket=owner.ticket();final VerifiedDriveAccess access=activeAccess;notifyChange(false);worker.execute(()->{Exception failure=null;try{runner.sync(owner,ticket,access);}catch(Exception e){failure=e;}final Exception problem=failure;dispatcher.execute(()->complete(g,owner,problem,true));});return true;
 }
 private synchronized void complete(long g,LedgerSession owner,Exception problem,boolean synced){if(closed||generation!=g||session!=owner)return;busy=false;if(problem==null){try{seenRevision=session.snapshot(session.ticket()).revision;}catch(Exception ignored){}if(!synced)SyncWorkScheduler.edited(context,subject);if(synced){lastSync=System.currentTimeMillis();try{new SyncStatusStore(context,subject).set("READY",true);}catch(Exception ignored){}}state=State.READY;}else if(problem instanceof DriveAppData.NeedsSignIn){if(activeAccess!=null)activeAccess.clear();activeAccess=null;state=State.NEEDS_SIGN_IN;}else if(problem instanceof SyncModel.Conflict||problem instanceof LedgerIntegrity.RepaymentConflict)state=State.CONFLICT;else if(problem instanceof BarrierRemote.ResetObserved){observedReset=((BarrierRemote.ResetObserved)problem).check;state=State.RESET_DETECTED;}else if(problem instanceof SyncEngine.ChangedDuringSync||problem instanceof DriveAppData.RetryLater)state=State.RETRY;else state=State.ERROR;if(session.resetPending()&&state!=State.NEEDS_SIGN_IN)state=State.RESET_PENDING;notifyChange(problem==null);}
 public synchronized void disconnect(String expectedSubject)throws Exception{disconnect(expectedSubject,GoogleRevokeAccess::revoke);}
 synchronized void disconnect(String expectedSubject,Revoke revoke)throws Exception{expected(expectedSubject);if(busy)throw new IllegalStateException("Wait for the current Google operation");AccountDirectory.Entry target=accounts.find(expectedSubject);if(target==null)throw new IllegalStateException("Account is no longer recorded");accounts.beginDisconnect(expectedSubject);if(activeAccess!=null)activeAccess.clear();if(pendingAccess!=null)pendingAccess.clear();activeAccess=pendingAccess=null;SyncWorkScheduler.selection(context,null);session.invalidateForms();busy=true;state=State.DISCONNECT_PENDING;final long g=generation;notifyChange(true);worker.execute(()->{Exception failure=null;try{revoke.revoke(context,target);accounts.disconnected(expectedSubject);}catch(Exception e){failure=e;}final boolean success=failure==null;dispatcher.execute(()->finishDisconnect(g,expectedSubject,success));});}
 private synchronized void finishDisconnect(long g,String target,boolean success){if(closed||generation!=g||!Objects.equals(subject,target))return;busy=false;if(!success){state=State.DISCONNECT_PENDING;notifyChange(false);return;}try{selectLocal();}catch(Exception e){state=State.ERROR;notifyChange(false);}}
 private interface Work {void run(LedgerSession session,LedgerSession.Ticket ticket,VerifiedDriveAccess access)throws Exception;}
 private boolean perform(Work task)throws Exception{open();if(subject!=null&&accounts.disconnectPending(subject))throw new IllegalStateException("Finish disconnecting this Google account first");if(busy)throw new IllegalStateException("Wait for the current sync");if(subject==null)throw new IllegalStateException("Choose a Google ledger first");if(activeAccess==null){state=State.NEEDS_SIGN_IN;notifyChange(false);return false;}try{activeAccess.accessToken(subject);}catch(DriveAppData.NeedsSignIn e){activeAccess.clear();activeAccess=null;state=State.NEEDS_SIGN_IN;notifyChange(false);return false;}final long g=generation;final LedgerSession owner=session;final LedgerSession.Ticket ticket=owner.ticket();final VerifiedDriveAccess access=activeAccess;busy=true;state=State.SYNCING;notifyChange(false);worker.execute(()->{Exception problem=null;try{task.run(owner,ticket,access);}catch(Exception e){problem=e;}final Exception result=problem;dispatcher.execute(()->complete(g,owner,result,false));});return true;}
 private void expected(String expected){open();if(subject==null||!subject.equals(expected))throw new IllegalStateException("Selected Google ledger changed. Review this action again.");}
 public synchronized boolean copyLocal(String expectedSubject)throws Exception{expected(expectedSubject);return perform((owner,ticket,access)->{try(LedgerSession local=LedgerSession.local(context)){owner.adoptLocal(ticket,local,local.ticket(),access);}});}
 public synchronized void beginReset(String expectedSubject)throws Exception{expected(expectedSubject);if(accounts.disconnectPending(subject))throw new IllegalStateException("Finish the Google disconnect first");if(busy||subject==null)throw new IllegalStateException("Choose an idle Google ledger");session.beginCloudReset(session.ticket());state=State.RESET_PENDING;notifyChange(false);}
 public synchronized boolean resumeReset()throws Exception{open();if(!session.resetPending())throw new IllegalStateException("No cloud reset is pending");return perform((owner,ticket,access)->owner.resumeCloudReset(ticket,access));}
 /** UI must explain the remote reset and obtain a separate discard confirmation. */
 public synchronized void acceptObservedReset(String expectedSubject)throws Exception{expected(expectedSubject);if(busy||observedReset==null)throw new IllegalStateException("No reset is ready for review");session.acknowledgeReset(session.ticket(),observedReset);observedReset=null;state=initialState();notifyChange(true);}
 synchronized RepaymentReviewStore.Review repaymentReview()throws Exception{open();return session.repaymentReview(session.ticket());}
 synchronized void removeReviewedRepayment(String key,long revision,String payment)throws Exception{open();if(busy)throw new IllegalStateException("Wait for sync to finish");session.removeReviewedRepayment(session.ticket(),key,revision,payment);state=initialState();notifyChange(true);}
 public synchronized ConflictReviewStore.Review conflict()throws Exception{open();return session.conflict(session.ticket());}
 public synchronized void resolveConflict(String reviewKey,long revision,int selected,boolean delete)throws Exception{open();if(busy)throw new IllegalStateException("Wait for sync to finish");session.resolveConflict(session.ticket(),reviewKey,revision,selected,delete);state=initialState();notifyChange(true);}
 @Override public synchronized void close(){if(closed)return;closed=true;generation=Math.addExact(generation,1);session.close();if(activeAccess!=null)activeAccess.clear();if(pendingAccess!=null)pendingAccess.clear();activeAccess=pendingAccess=null;worker.shutdownNow();}
}
